    "environment": "马舍要求干燥、通风、避风，适宜温度 5~25℃，湿度 40~70%，氨气 <20ppm。马怕潮湿闷热，夏季需遮阴降温，冬季防贼风。",
    "density": "成年马每匹需 3~4㎡ 厩舍、8~15㎡ 运动场；群养每栏不超过 8~10 匹，避免争斗。",
    "ventilation": "每小时换气 6~8 次，保持空气新鲜；避免穿堂风直吹马体。",
    "lighting": "自然光照为主，厩舍每日光照 8~12 小时；冬季可补光。",
    "diet": "粗饲料（干草、青草）为主，搭配精料（燕麦、玉米、豆粕）；每日饮水 30~50 升，运动后忌暴饮。",
    "water": "清洁饮水常备，冬季防冻；剧烈运动后先休息再少量饮水。",
    "immunity": "定期驱虫（每 2~3 个月），接种马流感、马腺疫、破伤风疫苗。",
    "hygiene": "每日清粪、勤换垫料；蹄部每 6~8 周修蹄钉掌；定期刷马。",
    "mistakes": "常见误区：运动后立即大量饮水、长期厩养缺乏运动、蹄部护理不到位导致蹄病。",
